	"CommonPrayers/TheotokionNone": {
		header: "бг҃оро́диченъ",
		text: "И҆́же на́съ ра́ди рожде́йсѧ ѿ дв҃ы, и҆ распѧ́тїе  претерпѣ́въ, бл҃гі́й, и҆спрове́ргїй сме́ртїю сме́рть, и҆  воскр҃се́нїе ꙗ҆вле́й ꙗ҆́кѡ бг҃ъ, не пре́зри ꙗ҆̀же  созда́лъ є҆сѝ рꙋко́ю твое́ю, ꙗ҆вѝ чл҃вѣколю́бїе  твоѐ, млⷭ҇тиве, прїимѝ ро́ждшꙋю тѧ̀ бцⷣꙋ молѧ́щꙋюсѧ за  ны̀, и҆ сп҃сѝ, сп҃се на́шъ, лю́ди ѿча̑ѧнныѧ.",
	},
	"CommonPrayers/TheotokionPr1": { text: "Стѡпы̀ моѧ̑ напра́ви по словесѝ твоемꙋ̀: и҆ да не ѡ҆блада́етъ мно́ю всѧ́кое беззако́нїе." },
	"CommonPrayers/TheotokionPr2": { text: "И҆зба́ви мѧ̀ ѿ клеветы̀ человѣ́ческїѧ, и҆ сохраню̀ за́пѡвѣди твоѧ̑." },
	"CommonPrayers/TheotokionPr3": { text: "Лицѐ твоѐ просвѣтѝ на раба̀ твоего̀, и҆ наꙋчи́ мѧ ѡ҆правда́нїємъ твои̑мъ." },
	"CommonPrayers/TheotokionPr4": {
		text: "Да и҆спо́лнѧтсѧ ѹ҆ста̀ моѧ̑ хвале́нїѧ твоегѡ̀ гⷭ҇и, ꙗ҆́кѡ да воспою̀ сла́вꙋ твою̀, ве́сь де́нь великолѣ́пїе твоѐ.",
	},
	"CommonPrayers/TheotokionPrimes": {
		header: "бг҃оро́диченъ",
		text: "Что́ тѧ нарече́мъ, ѽ бл҃года́тнаѧ; нб҃о, ꙗ҆́кѡ возсїѧ́ла є҆сѝ сл҃нце пра́вды: ра́й, ꙗ҆́кѡ прозѧбла̀ є҆сѝ цвѣ́тъ нетлѣ́нїѧ: дв҃ꙋ, ꙗ҆́кѡ пребыла̀ є҆сѝ нетлѣ́нна: чи́стꙋю мт̃рь, ꙗ҆́кѡ и҆мѣ́ла є҆сѝ на ст҃ы́хъ твои́хъ ѡ҆б̾ѧ́тїѧхъ сн҃а, всѣ́хъ бг҃а. того̀ молѝ сп҃сти́сѧ дꙋша́мъ на́шымъ.",
	},
	"CommonPrayers/TheotokionSext": {
		header: "бг҃оро́диченъ",
		text: "Ꙗ҆́кѡ не и҆́мамы дерзнове́нїѧ, за премнѡ́гїѧ грѣхѝ  на́шѧ: ты̀ и҆́же ѿ тебѐ ро́ждшагосѧ, молѝ, бцⷣе  дв҃о, мно́гѡ бо мо́жетъ моле́нїе ма́тернее, ко  бл҃госе́рдїю влⷣки. не пре́зри грѣ́шныхъ мѡльбы̀  всечⷭ҇таѧ, ꙗ҆́кѡ ми́лостивъ є҆́сть, и҆ сп҃стѝ могі́й,  и҆́же и҆ страда́ти ѡ҆ на́съ и҆зво́ливый.",
	},
	"CommonPrayers/TheotokionTerce": {
		header: "бг҃оро́диченъ",
		text: "Бцⷣе, ты̀ є҆сѝ лоза̀ и҆́стиннаѧ, возрасти́вшаѧ  на́мъ пло́дъ живота̀, тебѣ̀ мо́лимсѧ: моли́сѧ, влⷣчце,  со ст҃ы́ми а҆пⷭ҇лы, поми́ловати дꙋ́шы на́шѧ.",
	},
	"CommonPrayers/ThriceHoly": { text: "Ст҃ы́й бж҃е, ст҃ы́й крѣ́пкїй, ст҃ы́й безсме́ртный поми́лꙋй на́съ." },
	"CommonPrayers/ThroughPrayers": { text: "Моли́твами ст҃ы́хъ ѻ҆ц҃ъ на́шихъ гдⷭ҇и їи҃се хрⷭ҇те, бж҃е на́шъ, поми́лꙋй на́съ." },
	"CommonPrayers/VersTyp": { header: "", text: "Пристꙋпи́те къ немꙋ̀, и҆ просвѣти́тесѧ, и҆ ли́ца  ва̑ша не постыдѧ́тсѧ." },
	"CommonPrayers/Wisdom": { text: "Премꙋ́дрость." },
	"CommonPrayers/WisdomAttentive": { text: "Премꙋ́дрость. Во́нмемъ." },
